#!/bin/bash
# gen_man_pages.sh — bake docs/zh_CN/man pages into init/man_pages.c
#
# Each page becomes one C array; a table maps {name, section, data, len}
# so kmain can write them to /export/share/man/man<sec>/<name>.<sec>.
set -eu
cd "$(dirname "$0")/../../"

OUT=init/man_pages.c
OUTH=init/man_pages.h
mkdir -p init

cat > "$OUTH" << 'EOF'
/* Generated by tools/build/gen_man_pages.sh — DO NOT EDIT */
#ifndef _M4KK1_MAN_PAGES_H_
#define _M4KK1_MAN_PAGES_H_

struct mkrn_man_page {
    const char *name;
    int section;
    const unsigned char *data;
    unsigned int len;
};

extern const struct mkrn_man_page mkrn_man_pages[];

#endif
EOF

# sanitize a page name into a C identifier (dots/dashes -> underscore)
san() {
    echo "$1" | tr -c 'a-zA-Z0-9' '_'
}

{
echo "/* Generated by tools/build/gen_man_pages.sh — DO NOT EDIT"
echo " * Manual pages baked from docs/zh_CN/man at build time. */"
echo "#include <stdint.h>"
echo

for sec in 1 2 3 4 5 7 8; do
    d="docs/zh_CN/man/man${sec}"
    [ -d "$d" ] || continue
    for f in "$d"/*."${sec}"; do
        [ -f "$f" ] || continue
        base=$(basename "$f" ."${sec}")
        var="man_page_$(san "${base}")_${sec}"
        echo "static const unsigned char ${var}[] = {"
        xxd -i < "$f" | grep '^ ' | sed 's/^ *//'
        echo "};"
        echo "static const unsigned int ${var}_len = $(stat -c%s "$f");"
        echo
    done
done

echo "#include \"man_pages.h\""
echo "const struct mkrn_man_page mkrn_man_pages[] = {"
for sec in 1 2 3 4 5 7 8; do
    d="docs/zh_CN/man/man${sec}"
    [ -d "$d" ] || continue
    for f in "$d"/*."${sec}"; do
        [ -f "$f" ] || continue
        base=$(basename "$f" ."${sec}")
        var="man_page_$(san "${base}")_${sec}"
        echo "    { \"${base}\", ${sec}, ${var}, ${var}_len },"
    done
done
echo "    { 0, 0, 0, 0 }"
echo "};"
} > "$OUT"

echo "   Generated $OUT ($(grep -c 'static const unsigned char' "$OUT") pages)"
